/**
 * @module use-mobile
 *
 * Hooks de detecção de dispositivo orientation-aware.
 *
 * Modos suportados:
 * - `mobile`  → viewport &lt; 768px **OU** 768-1279px em portrait
 *               (tablets em retrato seguem layout mobile por escolha de produto)
 * - `tablet`  → viewport 768-1279px **em landscape** (iPad, Surface deitado)
 * - `desktop` → viewport ≥ 1280px (qualquer orientação)
 */

import * as React from 'react';
import { wideWarn } from '@/shared/lib/telemetry/wide-events';

/** Viewport máximo (exclusivo) considerado mobile sem condicionar orientação. */
const MOBILE_BREAKPOINT = 768;
/** Viewport máximo (exclusivo) da faixa tablet; daí em diante é desktop. */
const TABLET_BREAKPOINT = 1280;

export type DeviceMode = 'mobile' | 'tablet' | 'desktop';

/**
 * Lê o modo atual usando `matchMedia.matches` em vez de `window.innerWidth/Height`.
 *
 * Motivo: durante `orientationchange` no iOS, `window.innerWidth/Height` pode
 * ainda refletir a orientação anterior por ~100ms. `matchMedia.matches` é
 * gerenciado pelo browser e sempre retorna o estado atual das media queries,
 * portanto é confiável imediatamente.
 */
function readDeviceMode(): DeviceMode {
  if (typeof window === 'undefined') return 'desktop';
  if (
    window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches
  ) {
    return 'mobile';
  }
  if (
    window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`).matches
  ) {
    return 'desktop';
  }
  // 768 ≤ width < 1280: orientação decide.
  return window.matchMedia('(orientation: landscape)').matches
    ? 'tablet'
    : 'mobile';
}

/**
 * Retorna o modo de dispositivo atual: `mobile`, `tablet` ou `desktop`.
 * Reage a mudanças de viewport e orientação.
 */
export function useDeviceMode(): DeviceMode {
  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());

  React.useLayoutEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout> | undefined;

    const update = () => {
      setMode(readDeviceMode());
      // No iOS, durante rotação física, o viewport "settles" alguns frames
      // depois do evento. Re-checa após 250ms pra garantir sincronização.
      if (timeoutId) clearTimeout(timeoutId);
      timeoutId = setTimeout(() => setMode(readDeviceMode()), 250);
    };

    update();

    const queries = [
      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
      window.matchMedia(
        `(min-width: ${MOBILE_BREAKPOINT}px) and (max-width: ${TABLET_BREAKPOINT - 1}px)`,
      ),
      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
      window.matchMedia('(orientation: landscape)'),
      window.matchMedia('(orientation: portrait)'),
    ];
    queries.forEach((mq) => mq.addEventListener('change', update));
    window.addEventListener('resize', update);
    window.addEventListener('orientationchange', update);

    return () => {
      if (timeoutId) clearTimeout(timeoutId);
      queries.forEach((mq) => mq.removeEventListener('change', update));
      window.removeEventListener('resize', update);
      window.removeEventListener('orientationchange', update);
    };
  }, []);

  return mode;
}

/**
 * `true` quando o dispositivo deve usar layout mobile-essence.
 *
 * Filosofia: "essência mobile continua + adapta layout pra landscape". Por isso
 * inclui qualquer viewport não-desktop:
 *  - phones (&lt; 768px)
 *  - tablets em portrait (768-1279px, altura ≥ largura)
