function installMatchMedia() {
  // Não usar vi.fn() diretamente no `value` para evitar que vi.clearAllMocks()
  // remova a implementação. A função wrapper é uma função normal; só os métodos
  // internos do FakeMQL usam vi.fn() para que o hook possa registrar listeners.
  const impl = (query: string): FakeMQL => ({
    matches: evaluateMediaQuery(query),
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn(),
  });
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: impl,
  });
}

